nt(11) NOT NULL AUTO_INCREMENT PRIMARY KEY,\n  `itemName` varchar(255) NOT NULL,\n  `price` decimal(10,2) NOT NULL,\n  `image` varchar(255) NOT NULL,\n  `quantity` int(11) NOT NULL DEFAULT 1,\n  `catName` varchar(255) NOT NULL,\n  `email` varchar(255) NOT NULL,\n  `total_price` varchar(255) NOT NULL\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;\n\nCREATE TABLE IF NOT EXISTS `orders` (\n  `order_id` int(11) NOT NULL AUTO_INCREMENT PRIMARY KEY,\n  `email` varchar(255) NOT NULL,\n  `firstName` varchar(255) NOT NULL,\n  `lastName` varchar(255) NOT NULL,\n  `phone` varchar(255) NOT NULL,\n  `address` text NOT NULL,\n  `pmode` varchar(255) NOT NULL DEFAULT 'Cash on Delivery',\n  `payment_status` enum('pending','successful','failed') NOT NULL DEFAULT 'pending',\n  `sub_total` decimal(10,2) NOT NULL DEFAULT 0.00,\n  `grand_total` decimal(10,2) NOT NULL DEFAULT 0.00,\n  `order_date` timestamp NOT NULL DEFAULT current_timestamp(),\n  `order_status` enum('pending','confirmed','preparing','on-the-way','delivered','cancelled') NOT NULL DEFAULT 'pending',\n  `cancel_reason` text DEFAULT NULL,\n  `note` text DEFAULT NULL\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;\n\nCREATE TABLE IF NOT EXISTS `order_items` (\n  `id` int(11) NOT NULL AUTO_INCREMENT PRIMARY KEY,\n  `order_id` int(11) NOT NULL,\n  `itemName` varchar(255) NOT NULL,\n  `image` varchar(255) DEFAULT 'default.jpg',\n  `quantity` int(11) NOT NULL DEFAULT 1,\n  `price` decimal(10,2) NOT NULL DEFAULT 0.00,\n  `total_price` decimal(10,2) NOT NULL DEFAULT 0.00\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;\n\nCREATE TABLE IF NOT EXISTS `reservations` (\n  `reservation_id` int(11) NOT NULL AUTO_INCREMENT PRIMARY KEY,\n  `email` varchar(255) NOT NULL,\n  `name` varchar(255) NOT NULL,\n  `contact` varchar(255) NOT NULL,\n  `noOfGuests` int(11) NOT NULL DEFAULT 1,\n  `reservedTime` time NOT NULL,\n  `reservedDate` date NOT NULL,\n  `reservedAt` timestamp NOT NU